void Solver::bump_var(int var, double coeff) {
    double inc = var_inc * coeff;
    double newAct = activity[var] + inc;
    activity[var] = newAct;
    if (newAct > 1e100) {
        const double SCALE = 1e-100;
        double* p = activity + 1;
        double* end = p + vars;
        for (; p != end; ++p) {
            *p *= SCALE;
        }
        var_inc *= SCALE;
    }
    if (vsids.inHeap(var)) vsids.update(var);
}
